/*
 * Custom booking widget (demo). All client-specific values come from
 * window.FUNNEL_CONFIG (see funnels/clients/<id>/config.json).
 * Availability below is generated, not real. For production, swap
 * `slotsFor()` for a call to the Acuity Scheduling availability API and
 * `confirmBooking()` for an Acuity appointment create call.
 */
(function () {
  // Per-client settings, generated by scripts/build.js into assets/js/config.js.
  const SITE = window.FUNNEL_CONFIG;
  const CONFIG = Object.assign({ timeZone: SITE.timeZone }, SITE.booking);

  const BOOKED_KEY = SITE.id + ":booked_slots";
  const $ = (id) => document.getElementById(id);
  const money = (n) => SITE.currency + n.toFixed(2);
  const pad = (n) => String(n).padStart(2, "0");

  // ---------- date helpers (all dates are clinic-local calendar dates) ----------

  function clinicToday() {
    const parts = new Intl.DateTimeFormat("en-CA", { timeZone: CONFIG.timeZone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date());
    const get = (t) => Number(parts.find((p) => p.type === t).value);
    return { y: get("year"), m: get("month") - 1, d: get("day") };
  }

  const toUTC = ({ y, m, d }) => Date.UTC(y, m, d);
  const keyOf = ({ y, m, d }) => `${y}-${pad(m + 1)}-${pad(d)}`;
  const weekday = (date) => new Date(toUTC(date)).getUTCDay();
  const daysBetween = (a, b) => Math.round((toUTC(b) - toUTC(a)) / 86400000);

  function fmtDate(date, opts) {
    return new Date(toUTC(date)).toLocaleDateString("en-US", Object.assign({ timeZone: "UTC" }, opts));
  }

  function fmtTime(mins) {
    const h = Math.floor(mins / 60), m = mins % 60;
    return `${((h + 11) % 12) + 1}:${pad(m)} ${h < 12 ? "AM" : "PM"}`;
  }

  function tzLabel(date) {
    // Offset around midday on the selected date (handles daylight-saving switches).
    const probe = new Date(toUTC(date) + 19 * 3600000);
    let offset = "";
    try {
      offset = new Intl.DateTimeFormat("en-US", { timeZone: CONFIG.timeZone, timeZoneName: "longOffset" })
        .formatToParts(probe).find((p) => p.type === "timeZoneName").value;
    } catch (e) { /* older browsers */ }
    return `Time zone: ${SITE.timeZoneLabel}` + (offset ? ` (${offset})` : "");
  }

  // ---------- availability ----------

  function readBooked() {
    try { return JSON.parse(localStorage.getItem(BOOKED_KEY)) || {}; } catch (e) { return {}; }
  }

  function writeBooked(map) {
    try { localStorage.setItem(BOOKED_KEY, JSON.stringify(map)); } catch (e) {}
  }

  // Deterministic pseudo-random so a given day always shows the same "taken" slots.
  function seeded(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    return () => { h = Math.imul(h ^ (h >>> 15), 2246822507); h = Math.imul(h ^ (h >>> 13), 3266489909); return ((h ^= h >>> 16) >>> 0) / 4294967296; };
  }

  function isOpenDay(date) {
    const diff = daysBetween(today, date);
    return diff >= 1 && diff <= CONFIG.bookingWindowDays && !!CONFIG.hours[weekday(date)];
  }

  function slotsFor(date) {
    if (!isOpenDay(date)) return [];
    const [open, close] = CONFIG.hours[weekday(date)].map((t) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; });
    const length = CONFIG.service.minutes + selectedAddons().reduce((s, a) => s + a.minutes, 0);
    const rand = seeded(keyOf(date));
    const taken = readBooked()[keyOf(date)] || [];
    const out = [];
    for (let t = open; t + length <= close; t += CONFIG.slotMinutes) {
      if (rand() < 0.3) continue; // demo: ~30% already booked
      if (taken.includes(t)) continue;
      out.push(t);
    }
    return out;
  }

  // ---------- state ----------

  const today = clinicToday();
  const state = {
    view: "datetime",
    month: { y: today.y, m: today.m },
    date: null,
    time: null,
    addons: new Set(),
    coupon: null,
  };

  function selectedAddons() {
    return CONFIG.addons.filter((a) => state.addons.has(a.id));
  }

  function firstOpenDate() {
    for (let i = 1; i <= CONFIG.bookingWindowDays; i++) {
      const dt = new Date(toUTC(today) + i * 86400000);
      const date = { y: dt.getUTCFullYear(), m: dt.getUTCMonth(), d: dt.getUTCDate() };
      if (slotsFor(date).length) return date;
    }
    return null;
  }

  // ---------- rendering ----------

  function renderAddons() {
    $("addons").innerHTML = CONFIG.addons.map((a) => `
      <label class="addon">
        <input type="checkbox" value="${a.id}" ${state.addons.has(a.id) ? "checked" : ""}>
        <span class="addon-text"><strong>${a.name}</strong> - ${a.desc}</span>
        <span class="addon-meta">+ ${a.minutes} minutes @ ${money(a.price)}</span>
      </label>`).join("");
  }

  function renderCalendar() {
    const { y, m } = state.month;
    $("monthLabel").textContent = fmtDate({ y, m, d: 1 }, { month: "long", year: "numeric" });

    const lastAllowed = new Date(toUTC(today) + CONFIG.bookingWindowDays * 86400000);
    $("prevMonth").disabled = y === today.y && m === today.m;
    $("nextMonth").disabled = y > lastAllowed.getUTCFullYear() || (y === lastAllowed.getUTCFullYear() && m >= lastAllowed.getUTCMonth());

    const lead = weekday({ y, m, d: 1 });
    const count = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
    let html = "";
    for (let i = 0; i < lead; i++) html += "<span></span>";
    for (let d = 1; d <= count; d++) {
      const date = { y, m, d };
      const available = slotsFor(date).length > 0;
      const selected = state.date && keyOf(state.date) === keyOf(date);
      html += `<button type="button" class="day${selected ? " selected" : ""}" data-day="${d}" ${available ? "" : "disabled"}
        aria-label="${fmtDate(date, { weekday: "long", month: "long", day: "numeric" })}${available ? "" : ", unavailable"}"
        ${selected ? 'aria-pressed="true"' : ""}>${d}</button>`;
    }
    $("calDays").innerHTML = html;
    renderSlots();
  }

  // Phone-only sticky bar: keeps "Select and continue" in reach once a time is picked.
  function renderMobileCta() {
    const show = !$("scheduler").hidden && state.view === "datetime" && state.date && state.time != null;
    $("mCta").hidden = !show;
    document.body.classList.toggle("has-cta", !!show);
    if (show) $("mCtaWhen").textContent = `${fmtDate(state.date, { weekday: "short", month: "short", day: "numeric" })} · ${fmtTime(state.time)}`;
  }

  function renderSlots() {
    renderMobileCta();
    if (!state.date) {
      $("tzLabel").textContent = tzLabel(today);
      $("slots").innerHTML = `<p class="no-slots">Select a date to see available times.</p>`;
      return;
    }
    $("tzLabel").textContent = tzLabel(state.date);
    const slots = slotsFor(state.date);
    if (!slots.length) {
      $("slots").innerHTML = `<p class="no-slots">No times available on this day. Please choose another date.</p>`;
      return;
    }
    $("slots").innerHTML = slots.map((t) => {
      const sel = state.time === t;
      return `<button type="button" class="slot${sel ? " selected" : ""}" data-time="${t}">
        <span>${fmtTime(t)}</span><span class="go">Select and continue</span></button>`;
    }).join("");
  }

  function pricing() {
    const base = CONFIG.service.price;
    const addons = selectedAddons();
    const pct = state.coupon ? CONFIG.coupons[state.coupon] : 0;
    const discount = Math.round(base * pct) / 100;
    const total = base + addons.reduce((s, a) => s + a.price, 0) - discount;
    return { base, addons, pct, discount, total };
  }

  function whenText() {
    return `${fmtDate(state.date, { weekday: "long", month: "long", day: "numeric", year: "numeric" })} at ${fmtTime(state.time)}`;
  }

  function renderSummary() {
    const addons = selectedAddons();
    $("summary").innerHTML = `
      <p class="s-name">${CONFIG.service.name} with ${CONFIG.service.calendar}</p>
      <p class="s-when">${whenText()}</p>
      ${addons.map((a) => `<p class="s-add">+ ${a.name}</p>`).join("")}
      <button type="button" class="link-btn change" data-change>Change</button>`;
  }

  function renderTotals() {
    const p = pricing();
    $("totals").innerHTML = `
      <div><span>${CONFIG.service.name}</span><span>${money(p.base)}</span></div>
      ${p.addons.map((a) => `<div><span>${a.name}</span><span>${money(a.price)}</span></div>`).join("")}
      ${p.pct ? `<div class="discount"><span>${state.coupon} (${p.pct}% off scan)</span><span>-${money(p.discount)}</span></div>` : ""}
      <div class="total"><span>Total</span><span>${money(p.total)}</span></div>`;
  }

  function setView(view, scroll = true) {
    state.view = view;
    document.querySelectorAll("[data-view]").forEach((el) => { el.hidden = el.dataset.view !== view; });
    $("schedTitle").textContent = { datetime: "Date & Time", info: "Your Information", done: "Confirmation" }[view];
    $("schedBack").disabled = view !== "info";
    renderMobileCta();
    if (scroll) $("scheduler").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  function toast(msg) {
    const el = $("toast");
    el.textContent = msg;
    el.hidden = false;
    clearTimeout(toast.t);
    toast.t = setTimeout(() => { el.hidden = true; }, 2600);
  }

  // ---------- coupon ----------

  function applyCoupon(code, quiet) {
    const msg = $("couponMsg");
    code = (code || "").trim().toUpperCase();
    if (!code) { state.coupon = null; msg.textContent = ""; msg.className = "coupon-msg"; renderTotals(); return; }
    if (CONFIG.coupons[code]) {
      state.coupon = code;
      msg.textContent = `${code} applied – ${CONFIG.coupons[code]}% off your ${CONFIG.couponAppliesTo}.`;
      msg.className = "coupon-msg ok";
    } else {
      state.coupon = null;
      msg.textContent = quiet ? "" : "That code isn't valid.";
      msg.className = "coupon-msg bad";
    }
    renderTotals();
  }

  // ---------- events ----------

  $("apptToggle").addEventListener("click", () => {
    const open = $("apptDesc").classList.toggle("open");
    $("apptToggle").querySelector("span").textContent = open ? "Show less" : "Show all";
    $("apptToggle").classList.toggle("open", open);
    $("apptToggle").setAttribute("aria-expanded", String(open));
  });

  $("addons").addEventListener("change", (e) => {
    if (e.target.checked) state.addons.add(e.target.value); else state.addons.delete(e.target.value);
    // Longer appointment can change which times fit.
    if (state.date && state.time != null && !slotsFor(state.date).includes(state.time)) state.time = null;
    renderCalendar();
  });

  $("prevMonth").addEventListener("click", () => {
    const d = new Date(Date.UTC(state.month.y, state.month.m - 1, 1));
    state.month = { y: d.getUTCFullYear(), m: d.getUTCMonth() };
    renderCalendar();
  });

  $("nextMonth").addEventListener("click", () => {
    const d = new Date(Date.UTC(state.month.y, state.month.m + 1, 1));
    state.month = { y: d.getUTCFullYear(), m: d.getUTCMonth() };
    renderCalendar();
  });

  $("calDays").addEventListener("click", (e) => {
    const btn = e.target.closest("[data-day]");
    if (!btn || btn.disabled) return;
    state.date = { y: state.month.y, m: state.month.m, d: Number(btn.dataset.day) };
    state.time = null;
    renderCalendar();
  });

  $("slots").addEventListener("click", (e) => {
    const btn = e.target.closest("[data-time]");
    if (!btn) return;
    const t = Number(btn.dataset.time);
    if (state.time === t) return goToInfo();
    state.time = t;
    renderSlots();
    const sel = $("slots").querySelector(".slot.selected .go");
    if (sel) sel.closest(".slot").focus({ preventScroll: true });
  });

  function goToInfo() {
    renderSummary();
    renderTotals();
    setView("info");
  }

  $("mCtaBtn").addEventListener("click", goToInfo);

  // Clients with an offer card show the scheduler only after "Continue".
  const offerBtn = $("offerContinue");
  if (offerBtn) offerBtn.addEventListener("click", () => {
    $("scheduler").hidden = false;
    offerBtn.setAttribute("aria-expanded", "true");
    renderMobileCta();
    $("scheduler").scrollIntoView({ behavior: "smooth", block: "start" });
  });

  // Format phone as typed or autofilled.
  const phoneField = $("infoForm").elements.phone;
  ["input", "change"].forEach((ev) => phoneField.addEventListener(ev, () => {
    const d = phoneField.value.replace(/\D/g, "").replace(/^1(?=\d{10})/, "").slice(0, 10);
    phoneField.value = d.length < 4 ? d : d.length < 7 ? `(${d.slice(0, 3)}) ${d.slice(3)}` : `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
  }));

  $("schedBack").addEventListener("click", () => { if (state.view === "info") setView("datetime"); });

  $("summary").addEventListener("click", (e) => { if (e.target.matches("[data-change]")) setView("datetime"); });

  $("applyCoupon").addEventListener("click", () => applyCoupon($("infoForm").elements.coupon.value));
  $("infoForm").elements.coupon.addEventListener("keydown", (e) => {
    if (e.key === "Enter") { e.preventDefault(); applyCoupon(e.target.value); }
  });

  $("infoForm").addEventListener("submit", (e) => {
    e.preventDefault();
    const f = e.target.elements;
    const bad = [];
    ["firstName", "lastName"].forEach((k) => { if (!f[k].value.trim()) bad.push(f[k]); });
    if (f.phone.value.replace(/\D/g, "").replace(/^1(?=\d{10}$)/, "").length !== 10) bad.push(f.phone);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(f.email.value.trim())) bad.push(f.email);
    [f.firstName, f.lastName, f.phone, f.email].forEach((i) => i.classList.toggle("invalid", bad.includes(i)));
    const question = e.target.querySelector(".question");
    const answered = !question || !!e.target.querySelector("input[name=bonus]:checked");
    if (question) question.classList.toggle("invalid", !answered);
    if (!answered) bad.push(e.target.querySelector("input[name=bonus]"));
    if (bad.length) {
      $("infoError").textContent = "Please complete the highlighted fields.";
      bad[0].focus();
      return;
    }
    $("infoError").textContent = "";

    // Re-check the slot is still free (another tab may have booked it).
    if (!slotsFor(state.date).includes(state.time)) {
      toast("Sorry, that time was just taken. Please pick another.");
      state.time = null;
      renderCalendar();
      setView("datetime");
      return;
    }
    confirmBooking({
      firstName: f.firstName.value.trim(),
      lastName: f.lastName.value.trim(),
      phone: f.phone.value.trim(),
      email: f.email.value.trim().toLowerCase(),
    }, question ? e.target.querySelector("input[name=bonus]:checked").value : null);
  });

  function confirmBooking(client, bonus) {
    const booked = readBooked();
    const key = keyOf(state.date);
    booked[key] = (booked[key] || []).concat(state.time);
    writeBooked(booked);

    const p = pricing();
    const appointment = {
      service: CONFIG.service.name,
      date: key,
      time: fmtTime(state.time),
      timeZone: CONFIG.timeZone,
      addons: p.addons.map((a) => a.name),
      coupon: state.coupon,
      bonus,
      total: p.total,
    };
    const saved = LeadStore.saveLead(Object.assign({}, client, { status: "booked", appointment }));
    Track.event("Schedule", { value: p.total, currency: SITE.currencyCode }, saved.id);

    $("doneText").textContent = `Thanks ${client.firstName}, your appointment is confirmed.`;
    $("doneEmail").textContent = client.email;
    $("doneLines").innerHTML = `
      <div><span>Service</span><span>${CONFIG.service.name}${p.addons.length ? " + " + p.addons.map((a) => a.name).join(", ") : ""}</span></div>
      <div><span>When</span><span>${whenText()}</span></div>
      <div><span>Where</span><span>${SITE.name}</span></div>${appointment.bonus ? `<div><span>Free bonus</span><span>${appointment.bonus === "yes" ? "Yes" : "No"}</span></div>` : ""}
      <div><span>Total due</span><span>${money(p.total)}</span></div>`;
    setView("done");
  }

  $("icsBtn").addEventListener("click", () => {
    const length = CONFIG.service.minutes + selectedAddons().reduce((s, a) => s + a.minutes, 0);
    const stamp = (date, mins) => `${date.y}${pad(date.m + 1)}${pad(date.d)}T${pad(Math.floor(mins / 60))}${pad(mins % 60)}00`;
    const ics = [
      "BEGIN:VCALENDAR", "VERSION:2.0", `PRODID:-//${SITE.name}//Booking Demo//EN`,
      "BEGIN:VEVENT",
      `UID:${Date.now()}@${SITE.id}-demo`,
      `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+/, "")}`,
      `DTSTART;TZID=${CONFIG.timeZone}:${stamp(state.date, state.time)}`,
      `DTEND;TZID=${CONFIG.timeZone}:${stamp(state.date, state.time + length)}`,
      `SUMMARY:${CONFIG.service.name} – ${SITE.name}`,
      `DESCRIPTION:${CONFIG.icsDescription.replace(/[,;\\]/g, (ch) => "\\" + ch)}`,
      `LOCATION:${SITE.name}`,
      "END:VEVENT", "END:VCALENDAR",
    ].join("\r\n");
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([ics], { type: "text/calendar" }));
    a.download = "dexafit-appointment.ics";
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  });

  // ---------- init ----------

  const lead = Object.assign({}, LeadStore.lastKnown(), LeadStore.getLead());
  const form = $("infoForm").elements;
  form.firstName.value = lead.firstName || "";
  form.lastName.value = lead.lastName || "";
  form.email.value = lead.email || "";
  if (lead.phone) {
    const d = lead.phone.replace(/\D/g, "").slice(-10);
    form.phone.value = `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
  }
  form.coupon.value = CONFIG.defaultCoupon || "";
  applyCoupon(CONFIG.defaultCoupon, true);

  renderAddons();
  state.date = firstOpenDate();
  if (state.date) state.month = { y: state.date.y, m: state.date.m };
  renderCalendar();
  setView("datetime", false);
})();
